    ["太阳圣徽"] = "Священная эмблема Солнца",
    ["太阳圣徽-移动攻击盒结算"] = "Священная эмблема Солнца — расчёт подвижной зоны атаки",
    ["太阳圣徽-跳舞"] = "Священная эмблема Солнца — танец",
    ["太阳誓约"] = "Солнечная клятва",
    ["奇迹牌雨"] = "Дождь чудесных карт",
    ["姿态切换"] = "Смена стойки",
    ["学徒施放战斗技能会积攒星空能量和足迹，星空能量用于解锁和强化学徒的终结技能，足迹用于强化学徒的普通攻击。"] = "Применяя боевые навыки, Ученик накапливает энергию звёздного света и следы. Энергия звёздного света используется для разблокировки и усиления завершающих навыков Ученика, а следы — для усиления его обычных атак.",
    ["守护坚壁"] = "Оплот Хранителя",
    ["守护壁垒"] = "Стена Хранителя",
    ["安抚"] = "Умиротворение",
    ["寒冰刺骨"] = "Пронзающий холод",
    ["对15米内敌方玩家使用，影响其周围3米内目标，做下误导性<Highlight>暗示</>，持续<Highlight>2</>秒。\n被暗示的目标使用技能时造成的伤害会被转移到其友方上去，造成的治疗会被转移到其敌方上去。\n因精神错乱对友方造成的伤害无法直接击败友方。"] = "Применяется на вражеского игрока в пределах 15 м и воздействует на цели в радиусе 3 м от него, внушая ложное <Highlight>внушение</> на <Highlight>2</> сек.\nУрон от умений цели под внушением переносится на её союзников, а исцеление — на её врагов.\nУрон, нанесённый союзникам из-за безумия, не может напрямую их победить.",
    ["对前方小范围内敌方发动四段式攻击，分别造成*d/*d/sum(*d,*d,*d)/sum(*d,*d,*d,*d)点魔法伤害，第四段命中时<HyperLink stylename=\"M_Link\" u=\"2\">击退</>敌方怪物并使自身获得<HighLight>闪回</>。持有<HighLight>足迹</>时本技能替换为<HighLight>足迹再现</>。\n\n<FaintYellow>足迹再现</>\nskilldisc(*id)"] = "Проводит серию из 4 атак по врагам в небольшой области перед собой, наносящих *d/*d/sum(*d,*d,*d)/sum(*d,*d,*d,*d) ед. магического урона соответственно. При попадании 4-го удара <HyperLink stylename=\"M_Link\" u=\"2\">отбрасывает</> вражеских монстров и наделяет эффектом <HighLight>«Вспышка памяти»</>. При наличии <HighLight>«Следов»</> этот навык заменяется на <HighLight>«Воплощение следов»</>.\n\n<FaintYellow>Воплощение следов</>\nskilldisc(*id)",
    ["对前方小范围内的敌方施展三段式斩击，分别造成*d、*d+*d、*d点物理伤害并小幅度<HyperLink stylename=\"M_Link\" u=\"2\">击退</>敌方怪物；第三段命中后获得1点<HighLight>太阳能量</>。\nskilldisc(*id)\n\n<FaintYellow>太阳能量</>：最多持有5点，获取太阳能量以解锁与强化<HighLight>惩戒</>和<HighLight>无暗之枪</>。"] = "Совершает трехсегментный рубящий удар по противникам в небольшой зоне перед собой, нанося соответственно *d, *d+*d, *d ед. физического урона и слегка <HyperLink stylename=\"M_Link\" u=\"2\">отбрасывая</> монстров противника; попадание третьего сегмента дает 1 ед. <HighLight>Солнечной энергии</>.\nskilldisc(*id)\n\n<FaintYellow>Солнечная энергия</>: можно накапливать до 5 ед., получение солнечной энергии открывает и усиливает <HighLight>Кару</> и <HighLight>Копье Бессветия</>.",
    ["对前方小范围内的敌方进行连续的三段攻击，每段分别造成*d、*d和*d点物理伤害。第三段命中敌方后，自身获得1枚<HighLight>黄昏印记</>。\n\n<FaintYellow>黄昏印记</>\n使<HighLight>终结技能</>和<HighLight>怒意猛击</>得到强化，最多持有6枚。"] = "Наносит серию из трех ударов по врагам в небольшой области перед собой, причиняя *d, *d и *d ед. физического урона соответственно. При попадании третьего удара персонаж получает 1 <HighLight>Знак сумерек</>.\n\n<FaintYellow>Знак сумерек</>\nУсиливает <HighLight>добивающий навык</> и <HighLight>яростный удар</>. Можно накопить до 6 знаков.",
    ["对前方小范围内的敌方进行连续的三段攻击，每段攻击分别造成sum(*d+*d)、sum(*d+*d)和sum(*d+*d+*d)点物理伤害。第三段命中敌方时附加<Highlight>6</>秒<HighLight>衰败</>，同时自身获得1枚<HighLight>黄昏印记</>。\n\n<FaintYellow>黄昏印记</>\n使<HighLight>终结技能</>和<HighLight>怒意猛击</>得到强化，最多持有6枚。\n<FaintYellow>衰败</>\nbuffdisc(*id)，多次附加时长叠加，最多持续20秒。"] = "Выполните три последовательные атаки по врагу на небольшом расстоянии впереди, каждая атака наносит sum(*d+*d), sum(*d+*d) и sum(*d+*d+*d) очки физического урона соответственно. При попадании по врагу на третьем этапе будут добавлены дополнительные <Highlight>6</> секунд<HighLight>Decay</> и при этом вы получите 1 <HighLight>Twilight Mark</>. \n\n<FaintYellow>Сумеречная метка</>\n усиливает <HighLight> завершающие навыки </> и <HighLight>Яростный удар</>, вмещает до 6 частей. \n<FaintYellow>Decay</>\nbuffdisc(*id), накладывается несколько дополнительных длительностей продолжительностью до 20 секунд.",
    ["对前方扇形区域内的敌方进行三段式攻击，每段造成*d点物理伤害并<HyperLink stylename=\"M_Link\" u=\"2\">打断</>敌方怪物，第一段释放后自身6秒内buffdisc(*id)，第三段会附加一层<HighLight>愚弄标记</>并以*d**的基础概率将敌方<HyperLink stylename=\"M_Link\" u=\"2\">击退</>，附加*f秒mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">减疗</>，同时自身获得一张<HighLight>命运黄牌</>。\n\n<FaintYellow>命运黄牌</>/<FaintYellow>灵性蓝牌</>：获得三张<HighLight>命运黄牌</>/<HighLight>灵性蓝牌</>时消耗所有卡牌，使<HighLight>终结技能洗牌</>切换至<HighLight>命运愚弄</>/<HighLight>灵性爆发</>。\n<FaintYellow>愚弄标记</>：叠加3层后引爆并移除愚弄标记，受到施加者造成的mul(*d,3)点物理伤害。"] = "Совершает трехсегментную атаку по противникам в веерообразной зоне перед собой, каждый сегмент наносит *d ед. физического урона и <HyperLink stylename=\"M_Link\" u=\"2\">прерывает</> монстров противника. После применения первого сегмента на 6 сек. дает buffdisc(*id), третий сегмент накладывает 1 уровень <HighLight>Метки одурачивания</> и с базовой вероятностью *d** <HyperLink stylename=\"M_Link\" u=\"2\">отбрасывает</> противника, накладывая на *f сек. mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\">снижение исцеления</>, при этом заклинатель получает 1 <HighLight>Желтую карту судьбы</>.\n\n<FaintYellow>Желтая карта судьбы</>/<FaintYellow>Синяя карта духовности</>: при получении трех <HighLight>Желтых карт судьбы</>/<HighLight>Синих карт духовности</> расходуются все карты, заменяя <HighLight>Перетасовку карт (Завершающий навык)</> на <HighLight>Одурачивание судьбы</>/<HighLight>Всплеск духовности</>.\n<FaintYellow>Метка одурачивания</>: после накопления 3 уровней детонирует и снимается, нанося цели mul(*d,3) ед. физического урона от создателя.",
    ["对前方扇形区域内的敌方进行三段式攻击，每段造成*d点物理伤害并<HyperLink stylename=\"M_Link\" u=\"2\">打断</>敌方怪物，第三段会附加一层<HighLight>愚弄标记</>并以*d**的基础概率将敌方<HyperLink stylename=\"M_Link\" u=\"2\">击退</>，附加*f秒mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">减疗</>，同时自身获得一张<HighLight>命运黄牌</>。\n\n<FaintYellow>命运黄牌</>/<FaintYellow>灵性蓝牌</>：获得三张<HighLight>命运黄牌</>/<HighLight>灵性蓝牌</>时消耗所有卡牌，使<HighLight>终结技能洗牌</>切换至<HighLight>命运愚弄</>/<HighLight>灵性爆发</>。\n<FaintYellow>愚弄标记</>：叠加3层后引爆并移除愚弄标记，受到施加者造成的mul(*d,3)点物理伤害。"] = "Совершает трехсегментную атаку по противникам в веерообразной зоне перед собой, каждый сегмент наносит *d ед. физического урона и <HyperLink stylename=\"M_Link\" u=\"2\">прерывает</> монстров противника. Третий сегмент накладывает 1 уровень <HighLight>Метки одурачивания</> и с базовой вероятностью *d** <HyperLink stylename=\"M_Link\" u=\"2\">отбрасывает</> противника, накладывая на *f сек. mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\">снижение исцеления</>, при этом заклинатель получает 1 <HighLight>Желтую карту судьбы</>.\n\n<FaintYellow>Желтая карта судьбы</>/<FaintYellow>Синяя карта духовности</>: при получении трех <HighLight>Желтых карт судьбы</>/<HighLight>Синих карт духовности</> расходуются все карты, заменяя <HighLight>Перетасовку карт (Завершающий навык)</> на <HighLight>Одурачивание судьбы</>/<HighLight>Всплеск духовности</>.\n<FaintYellow>Метка одурачивания</>: после накопления 3 уровней детонирует и снимается, нанося цели mul(*d,3) ед. физического урона от создателя.",
    ["对前方范围内敌方发动刺击，造成*d点魔法伤害，命中时消耗全部<HighLight>足迹</>召唤残影进行追击（至多提升至*d点魔法伤害），并为敌方施加<HighLight>坠落</>，自身获得<HighLight>闪回</>。\n<FaintYellow>坠落</>\n使敌方怪物<HyperLink stylename=\"M_Link\" u=\"2\">浮空</>。若消耗2层以上<HighLight>足迹</>，有<HighLight>42%</>的基础概率对敌方施加*f秒buffdisc(*id)的效果，若消耗3层<HighLight>足迹</>，有<HighLight>70%</>的基础概率使敌方玩家<HyperLink stylename=\"M_Link\" u=\"2\">浮空</>，玩家目标被本技能<HyperLink stylename=\"M_Link\" u=\"2\">浮空</>后，短时间内无法再次被本技能<HyperLink stylename=\"M_Link\" u=\"2\">浮空</>。\n<FaintYellow>闪回</>\n减少<HighLight>放逐</>、<HighLight>星云咏叹</>、<HighLight>戏法演绎</>、<HighLight>记录</>1秒冷却时间，若消耗3层<HighLight>足迹</>，额外减少<HighLight>skillname(*id)</>2秒冷却时间。"] = "Наносит колющий удар по врагам перед собой, причиняя *d ед. магического урона. При попадании расходует все <HighLight>Следы</>, призывая остаточное изображение для добивания (урон увеличивается вплоть до *d ед. магического урона), накладывает на врагов эффект <HighLight>Падение</>, а сам персонаж получает <HighLight>Флешбэк</>.`n<FaintYellow>Падение</>`n<HyperLink stylename=\"M_Link\" u=\"2\">Подбрасывает</> вражеских монстров. Если израсходовано более 2 зарядов <HighLight>Следов</>, с базовой вероятностью <HighLight>42%</> накладывает эффект buffdisc(*id) на *f сек. Если израсходовано 3 заряда <HighLight>Следов</>, с базовой вероятностью <HighLight>70%</> <HyperLink stylename=\"M_Link\" u=\"2\">подбрасывает</> вражеских игроков. Игрок, <HyperLink stylename=\"M_Link\" u=\"2\">подброшенный</> данным навыком, не может быть <HyperLink stylename=\"M_Link\" u=\"2\">подброшен</> им повторно в течение короткого времени.`n<FaintYellow>Флешбэк</>`nСокращает время перезарядки навыков <HighLight>Изгнание</>, <HighLight>Ария туманности</>, <HighLight>Исполнение фокуса</> и <HighLight>Запись</> на 1 сек. При расходе 3 зарядов <HighLight>Следов</> дополнительно снижает перезарядку <HighLight>skillname(*id)</> на 2 сек.",
    ["对前方范围内敌方造成spellfielddisc(*id)点魔法伤害，附加*f秒mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">减疗</>并以*d**的基础概率附加持续*f秒的buffdisc(*id)。\n仅<HighLight>噩梦姿态</>可用，<HighLight>空想姿态</>下切换为<HighLight>读心</>。"] = "Наносит врагам в области перед собой spellfielddisc(*id) ед. магического урона, накладывает на *f сек. mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\">снижения эффективности лечения</> и с базовой вероятностью *d** накладывает buffdisc(*id) на *f сек.\nДоступно только в <HighLight>стойке «Кошмар»</>; в <HighLight>стойке «Фантазия»</> сменяется на навык <HighLight>«Чтение мыслей»</>.",
    ["对友方发射治疗子弹，回复其bulletdisc(*id)点生命。治疗子弹在命中目标后会向其小队或团队队友弹射，为下一个目标回复生命。弹射最多发生3次，每次弹射都会使子弹的治疗量降低30%。"] = "Выпускает в союзника исцеляющую пулю, восстанавливая ему bulletdisc(*id) ед. здоровья. При попадании в цель пуля рикошетит в соратников по отряду или группе, исцеляя следующую цель. Рикошет может произойти до 3 раз, и каждый отскок снижает исцеление пули на 30%.",
    ["对周身范围内敌方造成spellfielddisc(*id)点魔法伤害并将其<HyperLink stylename=\"M_Link\" u=\"2\">击退</>，移除敌方spellfielddisc(*id)点护盾，施加持续*f秒的mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">减疗</>。施法后<HighLight>5</>秒内可以连招施法，使自身快速向后位移。施法后获得20点<HighLight>神秘知识</>。\n\n<FaintYellow>神秘知识</>：最多拥有100点。达到100点时解锁<HighLight>终结技能信息洪流</>。"] = "Наносит врагам вокруг себя spellfielddisc(*id) ед. магического урона, <HyperLink stylename=\"M_Link\" u=\"2\">отбрасывает</> их, снимает spellfielddisc(*id) ед. вражеского щита и накладывает mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\">снижения лечения</> на *f сек. В течение <HighLight>5</> сек. после применения навык можно повторить в комбо, чтобы быстро совершить отскок назад. Применение дает 20 ед. <HighLight>Оккультных знаний</>.\n\n<FaintYellow>Оккультные знания</>: максимум 100 ед. При накоплении 100 ед. открывает доступ к <HighLight>абсолютному навыку «Поток информации»</>.",
    ["对敌方玩家使用误导性暗示，使其精神错乱。"] = "Использует на вражеском игроке ложное внушение, вызывая у него помутнение рассудка.",
    ["对敌方目标造成*d点物理伤害，同时有附加*f秒<HyperLink stylename=\"M_Link\" u=\"6\">眩晕</>和*f秒buffdisc(*id)的效果。"] = "Наносит *d физ. урона вражеской цели, одновременно применяя <HyperLink stylename=\"M_Link\" u=\"6\">Stun</> на *f сек. и на *f сек. эффект buffdisc(*id).",
    ["对最多6个目标同时生效，持续6s；持续时间内，目标防御降低，并受到伤害，对梦境编织内和受到精神瘟疫的敌人造成定身。"] = "Действует одновременно на количество целей до 6 на протяжении 6 сек.; во время действия защита целей снижается, и они получают урон. Враги внутри «Плетения снов» и пораженные «Душевной чумой» обездвиживаются.",
    ["对目标位置对敌人造成多次伤害"] = "Наносит врагам в указанной области многократный урон.",
    ["对目标进行一轮纯白射线打击，一共攻击5次，每次造成伤害递增，此伤害会根据范围内命中目标数衰减，最多3人分摊"] = "Обрушивает на цель серию ударов Чисто белыми лучами: всего 5 атак, урон каждой последующей возрастает. Этот урон снижается в зависимости от числа пораженных целей в зоне действия и распределяется максимум между 3 целями.",
    ["对目标进行积极的心理暗示，立刻为目标回复大量生命值，并为其提供短暂的减伤效果。"] = "Применяет к цели позитивное психологическое внушение, мгновенно восстанавливая ей значительное количество здоровья и даруя кратковременное Снижение урона.",
    ["对范围内敌方施加<HyperLink stylename=\"M_Link\" u=\"9\">滞涩</>与移动速度降低50%的效果，并造成5次*d点魔法伤害，同时<HyperLink stylename=\"M_Link\" u=\"2\">拖拽</>敌方怪物，随后终结一击造成*d点魔法伤害，<HyperLink stylename=\"M_Link\" u=\"2\">浮空</>敌方怪物。\n拥有<HighLight>研习</>（施放战斗技能<HighLight>空间牢笼</>以进入<HighLight>研习</>状态）时获得<HighLight>强化</>，对范围内敌方造成的5次伤害每一次提升至*d点。终结一击造成的伤害提升至*d点。"] = "Накладывает на врагов в области действия эффект <HyperLink stylename=\"M_Link\" u=\"9\">Замедления</> и снижает скорость передвижения на 50%, нанося 5 ударов по *d ед. магического урона и одновременно <HyperLink stylename=\"M_Link\" u=\"2\">притягивая</> вражеских монстров. Затем наносит завершающий удар, причиняющий *d ед. магического урона и <HyperLink stylename=\"M_Link\" u=\"2\">подбрасывающий</> монстров в воздух.\nПри наличии статуса <HighLight>Изучение</> (примените боевой навык <HighLight>Пространственная клетка</>, чтобы войти в состояние <HighLight>Изучение</>) получает <HighLight>Усиление</>: каждый из 5 ударов по врагам в области действия усиливается до *d ед. урона, а урон от завершающего удара возрастает до *d ед.",
    ["对范围内敌方造成*d点魔法伤害，并附加*f秒<HighLight>瘟疫</>。\n\n<FaintYellow>瘟疫</>：buffdisc(*id)。"] = "Наносит *d ед. магического урона врагам в зоне действия и накладывает эффект <HighLight>Чума</> на *f сек.\n\n<FaintYellow>Чума</>: buffdisc(*id).",
    ["对范围内敌方造成5次*d点魔法伤害，同时<HyperLink stylename=\"M_Link\" u=\"2\">拖拽</>敌方怪物，随后终结一击造成*d点魔法伤害，<HyperLink stylename=\"M_Link\" u=\"2\">浮空</>敌方怪物。\n拥有<HighLight>研习</>（施放战斗技能<HighLight>空间牢笼</>以进入<HighLight>研习</>状态）时获得<HighLight>强化</>，对范围内敌方造成的5次伤害每一次提升至*d点。终结一击造成的伤害提升至*d点。"] = "Наносит врагам в области действия магический урон *d ед. 5 раз, одновременно <HyperLink stylename=\"M_Link\" u=\"2\">притягивая</> вражеских монстров, после чего завершающий удар наносит *d ед. магического урона и <HyperLink stylename=\"M_Link\" u=\"2\">подбрасывает</> вражеских монстров в воздух.\nПри наличии эффекта <HighLight>Изучение</> (используйте боевой навык <HighLight>Пространственная клетка</>, чтобы войти в состояние <HighLight>Изучение</>) получает <HighLight>Усиление</>: каждый из 5 ударов по врагам в области повышается до *d ед. урона, а урон завершающего удара увеличивается до *d ед.",
    ["对范围内敌方造成spellfielddisc(*id)点物理伤害并有*f**的基础概率附加*f秒buffdisc(*id)的效果，同时以*f**的基础概率<HyperLink stylename=\"M_Link\" u=\"6\">眩晕</>范围中心的敌方0.8秒，最多<HyperLink stylename=\"M_Link\" u=\"6\">眩晕</>2人。命中敌方玩家时，对其附加*f秒mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">减疗</>。施法后获得一张<HighLight>命运黄牌</>，对命中的敌方附加一层<HighLight>愚弄标记</>；若上次获得为<HighLight>灵性蓝牌</>，则改为获得一张<HighLight>灵性蓝牌</>，同时获得一点<HighLight>卡牌能量</>。\n\n<FaintYellow>命运黄牌</>/<FaintYellow>灵性蓝牌</>：获得三张<HighLight>命运黄牌</>/<HighLight>灵性蓝牌</>时消耗所有卡牌，使<HighLight>终结技能洗牌</>切换至<HighLight>命运愚弄</>/<HighLight>灵性爆发</>。\n<FaintYellow>卡牌能量</>：最多持有5点，达到5点时<HighLight>终结技能</>切换并锁定为<HighLight>洗牌</>。\n<FaintYellow>愚弄标记</>：叠加3层后引爆并移除愚弄标记，受到施加者造成的mul(*d,3)点物理伤害。"] = "Наносит врагам в области действия spellfielddisc(*id) ед. физического урона с базовой вероятностью *f** наложить на *f сек. эффект buffdisc(*id), а также с базовой вероятностью *f** <HyperLink stylename=\"M_Link\" u=\"6\">оглушить</> врагов в центре области на 0,8 сек. (до 2 целей). При попадании по вражескому игроку накладывает на *f сек. эффект mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\">снижения исцеления</>. После применения даёт 1 <HighLight>Жёлтую карту судьбы</> и накладывает на поражённых врагов 1 ур. <HighLight>метки одурачивания</>; если последней полученной картой была <HighLight>Синяя карта духовности</>, вместо этого даёт 1 <HighLight>Синюю карту духовности</> и 1 ед. <HighLight>энергии карт</>.\n\n<FaintYellow>Жёлтая карта судьбы</> / <FaintYellow>Синяя карта духовности</>: при сборе 3 <HighLight>Жёлтых карт судьбы</> / <HighLight>Синих карт духовности</> расходует все карты, переключая <HighLight>завершающий навык «Тасование»</> на <HighLight>«Одурачивание судьбы»</> / <HighLight>«Всплеск духовности»</>.\n<FaintYellow>Энергия карт</>: накапливается до 5 ед.; при 5 ед. <HighLight>завершающий навык</> переключается и фиксируется на <HighLight>«Тасовании»</>.\n<FaintYellow>Метка одурачивания</>: при накоплении 3 ур. взрывается и спадает, нанося цели mul(*d,3) ед. физического урона от заклинателя.",
    ["对范围内敌方造成spellfielddisc(*id)点魔法伤害，并附加*f秒<HighLight>易伤</>。\n\n<FaintYellow>易伤</>：buffdisc(*id)5%。"] = "Наносит врагам в области действия spellfielddisc(*id) ед. магического урона и накладывает <HighLight>Уязвимость</> на *f сек.\n\n<FaintYellow>Уязвимость</>: buffdisc(*id)5%.",
    ["对范围内的敌方造成spellfielddisc(*id)点魔法伤害和*f秒mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">减疗</>，并随机附加<HighLight>落石</>、<HighLight>冰冻</>、<HighLight>飓风</>中的一种。\n拥有<HighLight>研习</>（施放战斗技能<HighLight>空间牢笼</>以进入<HighLight>研习</>状态）时获得<HighLight>强化</>，施法后召唤残影再次对范围内敌方进行攻击，造成spellfielddisc(*id)点魔法伤害并在命中后获得1点<HighLight>星空能量</>。\n\n<FaintYellow>落石</>\n对范围内敌方造成spellfielddisc(*id)点魔法伤害并附加灼烧，使其buffdisc(*id)，同时<HyperLink stylename=\"M_Link\" u=\"2\">击倒</>敌方怪物。\n<FaintYellow>冰冻</>\n对范围内敌方造成spellfielddisc(*id)点魔法伤害并有<HighLight>66%</>的基础概率附加*f秒buffdisc(*id)的效果，同时<HyperLink stylename=\"M_Link\" u=\"13\">冻结</>敌方怪物。\n<FaintYellow>飓风</>\n召唤飓风持续<HyperLink stylename=\"M_Link\" u=\"2\">拖拽</>敌方怪物并造成6次spellfielddisc(*id)点魔法伤害，最后一击<HyperLink stylename=\"M_Link\" u=\"2\">击倒</>敌方怪物。"] = "Наносит магический урон spellfielddisc(*id) и *f секунд mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">уменьшенное лечение</> врагам в радиусе действия и случайным образом добавляет одно из <HighLight>rockfall</>, <HighLight>freezing</>, <HighLight>hurricane</>. \n обладает <HighLight> исследованием</> (примените боевой навык <HighLight> «Космическая клетка» </>, чтобы войти в состояние <HighLight> исследования </>) и получите улучшение <HighLight> </>. После применения заклинания он вызывает остаточное изображение, чтобы снова атаковать врага в радиусе действия, нанося магический урон spellfielddisc(*id) и получая 1 очко <HighLight>звездной энергии</> после удара. \n\n<FaintYellow>Falling Rock</>\n наносит магический урон spellfielddisc(*id) и дополнительный ожог врагам в радиусе действия, делая их buffdisc(*id). В то же время <HyperLink stylename=\"M_Link\" u=\"2\"> сбивает с ног вражеских монстров </>. \n<FaintYellow>Freeze</>\n наносит магический урон врагам в радиусе действия spellfielddisc(*id) и имеет базовую вероятность <HighLight>66%</> добавить эффект buffdisc(*id) на *f секунд. В то же время <HyperLink stylename=\"M_Link\" u=\"13\"> замораживает </> вражеских монстров. \n<FaintYellow>ураган</>\nвызывает ураган, который длится<HyperLink stylename=\"M_Link\" u=\"2\">затягивает</>вражеских монстров и наносит 6 очков магического урона spellfielddisc(*id). Последний удар<HyperLink stylename=\"M_Link\" u=\"2\"> сбивает с ног </>вражеских монстров.",
    ["对范围内的敌方造成spellfielddisc(*id)点魔法伤害，并随机附加<HighLight>落石</>、<HighLight>冰冻</>、<HighLight>飓风</>中的一种。\n拥有<HighLight>研习</>（施放战斗技能<HighLight>空间牢笼</>以进入<HighLight>研习</>状态）时获得<HighLight>强化</>，施法后召唤残影再次对范围内敌方进行攻击，造成spellfielddisc(*id)点魔法伤害并在命中后获得1点<HighLight>星空能量</>。\n\n<FaintYellow>落石</>\n对范围内敌方造成spellfielddisc(*id)点魔法伤害并附加灼烧，使其buffdisc(*id)，同时<HyperLink stylename=\"M_Link\" u=\"2\">击倒</>敌方怪物。\n<FaintYellow>冰冻</>\n对范围内敌方造成spellfielddisc(*id)点魔法伤害并有<HighLight>66%</>的基础概率附加*f秒buffdisc(*id)的效果，同时<HyperLink stylename=\"M_Link\" u=\"13\">冻结</>敌方怪物。\n<FaintYellow>飓风</>\n召唤飓风持续<HyperLink stylename=\"M_Link\" u=\"2\">拖拽</>敌方怪物并造成6次spellfielddisc(*id)点魔法伤害，最后一击<HyperLink stylename=\"M_Link\" u=\"2\">击倒</>敌方怪物。"] = "Наносит врагам в области действия spellfielddisc(*id) ед. магического урона и случайным образом накладывает один из эффектов: <HighLight>Камнепад</>, <HighLight>Заморозка</> или <HighLight>Ураган</>.\nЕсли у вас есть статус <HighLight>Изучение</> (примените боевой навык <HighLight>Пространственная клетка</>, чтобы войти в состояние <HighLight>Изучение</>), вы получаете <HighLight>Усиление</>; после применения навыка призывается остаточный образ, который повторно атакует врагов в области действия, нанося spellfielddisc(*id) ед. магического урона и даруя 1 ед. <HighLight>Звездной энергии</> при попадании.\n\n<FaintYellow>Камнепад</>\nНаносит врагам в области действия spellfielddisc(*id) ед. магического урона, накладывает горение и buffdisc(*id), а также <HyperLink stylename=\"M_Link\" u=\"2\">сбивает с ног</> врагов.\n<FaintYellow>Заморозка</>\nНаносит врагам в области действия spellfielddisc(*id) ед. магического урона с базовой вероятностью <HighLight>66%</> наложить на *f сек. эффект buffdisc(*id), одновременно <HyperLink stylename=\"M_Link\" u=\"13\">замораживая</> врагов.\n<FaintYellow>Ураган</>\nПризывает ураган, который непрерывно <HyperLink stylename=\"M_Link\" u=\"2\">притягивает</> вражеских монстров и наносит 6 ударов по spellfielddisc(*id) ед. магического урона, причем последний удар <HyperLink stylename=\"M_Link\" u=\"2\">сбивает с ног</> врагов.",
    ["对身前圆形范围内敌方造成*d点魔法伤害。\n拥有<HighLight>研习</>（施放战斗技能<HighLight>空间牢笼</>以进入<HighLight>研习</>状态）时获得<HighLight>强化</>，施法后召唤残影再次对范围内敌方进行攻击，造成spellfielddisc(*id)点魔法伤害并在命中后获得1点<HighLight>星空能量</>。"] = "Наносит врагам в круглой области перед собой *d ед. магического урона.\nПри наличии эффекта <HighLight>Изучение</> (переход в состояние <HighLight>Изучение</> происходит после применения боевого навыка <HighLight>Пространственная клетка</>) навык получает <HighLight>Усиление</>: после применения призывается остаточный фантом, который повторно атакует врагов в зоне действия, нанося spellfielddisc(*id) ед. магического урона и давая 1 очко <HighLight>Звездной энергии</> при попадании.",
    ["对身前圆形范围内敌方造成*d点魔法伤害，并附加*f秒mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">减疗</>。\n拥有<HighLight>研习</>（施放战斗技能<HighLight>空间牢笼</>以进入<HighLight>研习</>状态）时获得<HighLight>强化</>，施法后召唤残影再次对范围内敌方进行攻击，造成spellfielddisc(*id)点魔法伤害并在命中后获得1点<HighLight>星空能量</>。"] = "Наносит *d ед. магического урона врагам в круговой области перед собой и накладывает mul(*d%,*d) <HyperLink stylename=\"M_Link\" u=\"20\">снижение исцеления</> на *f сек.\nПри наличии состояния <HighLight>Изучение</> (примените боевой навык <HighLight>Пространственная клетка</>, чтобы войти в состояние <HighLight>Изучение</>) получает <HighLight>Усиление</>: после применения навыка призывает остаточный образ, который повторно атакует врагов в области, нанося spellfielddisc(*id) ед. магического урона и даруя 1 ед. <HighLight>Энергии туманности</> при попадании.",
    ["对锁定目标及其周围敌方造成spellfielddisc(*id)点魔法伤害，并<HyperLink stylename=\"M_Link\" u=\"2\">浮空</>处于<HighLight>瘟疫</>状态的敌方怪物。"] = "Наносит маг. урона spellfielddisc(*id) заблокированной цели и окружающим врагам, а также <HyperLink stylename=\"M_Link\" u=\"2\"> плавает по </> вражеским монстрам в состоянии <HighLight>Plague</>.",
    ["对锁定目标方向矩形范围内的敌方造成*d点物理伤害，同时将其<HyperLink stylename=\"M_Link\" u=\"2\">拖拽</>至身前并对敌方玩家附加<HighLight>2秒</><HyperLink stylename=\"M_Link\" u=\"9\">滞涩</>，随后下劈对周身范围内敌方造成*d点物理伤害，有*f**的基础概率给敌方玩家附加*f秒<HyperLink stylename=\"M_Link\" u=\"7\">禁锢</>，并对敌方玩家造成*f秒mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">减疗</>。命中敌方后，自身获得1枚<HighLight>黄昏印记</>。\n自身处于<HighLight>防御形态</>时，若技能的锁定目标为怪物，对其附加*f秒<HyperLink stylename=\"M_Link\" u=\"12\">嘲讽</>。\n\n<FaintYellow>黄昏印记</>\n使<HighLight>终结技能</>和<HighLight>怒意猛击</>得到强化，最多持有6枚。"] = "Наносит *d ед. физического урона противникам в прямоугольной зоне по направлению захваченной цели, одновременно <HyperLink stylename=\"M_Link\" u=\"2\">притягивая</> их к себе и накладывая на вражеских игроков <HighLight>2 сек.</><HyperLink stylename=\"M_Link\" u=\"9\">замедления</>, затем обрушивает удар вниз, нанося *d ед. физического урона противникам вокруг себя. С базовой вероятностью *f** накладывает на вражеских игроков на *f сек. <HyperLink stylename=\"M_Link\" u=\"7\">обездвиживание</> и на *f сек. mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\">снижение исцеления</>. При попадании по противнику дает 1 <HighLight>Сумеречную метку</>.\nВ <HighLight>Оборонительной стойке</>, если целью является монстр, накладывает на него на *f сек. <HyperLink stylename=\"M_Link\" u=\"12\">провокацию</>.\n\n<FaintYellow>Сумеречная метка</>\nУсиливает <HighLight>Завершающий навык</> и <HighLight>Яростный сокрушительный удар</>, можно накопить до 6 шт.",
    ["对锁定目标造成*d点魔法伤害，自身获得<HighLight>知识灌注</>，并且buffdisc(*id)持续*d秒。施法后获得20点<HighLight>神秘知识</>。\n\n<FaintYellow>知识灌注</>：使下一次<HighLight>巫术</>（普通攻击）得到<HighLight>强化</>。使下两次释放的<HighLight>光之折射</>、<HighLight>星沙</>或<HighLight>星光囚笼</>得到<HighLight>强化</>，一次<HighLight>知识灌注</>只能强化同一技能最多一次。\n<FaintYellow>神秘知识</>：最多拥有100点。达到100点时解锁<HighLight>终结技能信息洪流</>。"] = "Наносит *d единиц магического урона заблокированной цели, получает <HighLight>infusion</> и buffdisc(*id) длится *d секунд. Получите 20 очков <HighLight> Таинственного Знания</> после применения. \n\n<FaintYellow>Вливание знаний</>: Сделайте так, чтобы следующее <HighLight>Колдовство</> (обычная атака) получило <HighLight> усиление</>. Следующие два выпущенных <HighLight>Refraction of Light</>, <HighLight>Star Sand</> или <HighLight>Starlight Cage</> будут <HighLight> усиленными</>. <HighLight>Вливание знаний</> может усилить один и тот же навык максимум один раз. \n<FaintYellow>Таинственное знание</>: Наберите до 100 очков. Разблокируйте <HighLight> при достижении 100 очков, чтобы положить конец потоку информации о навыках </>.",
    ["对锁定目标造成伤害"] = "Наносит урон заблокированной цели",
    ["对锁定目标造成伤害A以及加buff，对其周围5米内目标造成伤害B"] = "Наносит урон А и накладывает бафф на захваченную цель, а также наносит урон B целям в радиусе 5 м вокруг нее",
    ["对锁定目标造成伤害A，并在其位置释放法术场"] = "Наносит урон А зафиксированной цели и создаёт магическое поле в точке её нахождения.",
    ["将巨剑贯入地面崩解周身的现实，保持霸体状态持续蓄力并对自身周围的敌人造成伤害，蓄力结束后发动终结一击造成大量伤害并引爆衰败，剩余时长越长伤害越高，在拥有黄昏印记时得到强化。"] = "Вонзает двуручный меч в землю, искажая окружающую реальность; сохраняя Суперброню, непрерывно накапливает заряд и наносит урон окружающим врагам. По завершении накопления наносит завершающий удар, причиняющий огромный урон и взрывающий Увядание; чем больше времени оставалось, тем выше урон. Усиливается при наличии Знака Сумерек.",
    ["将巨剑贯入地面崩解周身的现实，持续霸体，在自身周围造成受自身最大生命加成的范围伤害，并且为低生命的友方提供高额护盾和减伤，在拥有黄昏印记时得到强化。"] = "Вонзает двуручный меч в землю, искажая окружающую реальность, и получает непрерывную Суперброню. Наносит урон по области вокруг себя, зависящий от максимального запаса здоровья, а также дарует прочный щит и Снижение урона союзникам с низким здоровьем. Усиливается при наличии Знака Сумерек.",
    ["将巨剑贯入地面崩解周身的现实，持续霸体，在自身周围造成受自身最大生命加成的范围伤害，并且为大范围内友方提供护盾，在拥有黄昏印记时得到强化。"] = "Вонзает двуручный меч в землю, искажая окружающую реальность, и получает непрерывную Суперброню. Наносит урон по области вокруг себя, зависящий от максимального запаса здоровья, а также дарует щит союзникам в широком радиусе. Усиливается при наличии Знака Сумерек.",
    ["将灵性凝聚出巨人实体，共同发动终结斩击，造成大量伤害的同时对敌方玩家施加减疗。释放后获得4枚黄昏印记（用于强化怒意猛击和终结技能）。"] = "Материализует исполина из духовности и совершает совместный добивающий рубящий удар, нанося огромный урон и снижая эффективность исцеления вражеских игроков. После применения дарует 4 Знака Сумерек (используются для усиления «Яростного удара» и завершающих навыков).",
    ["将自身的<HighLight>卡牌能量</>补至5点，释放时每有1点<HighLight>卡牌能量</>降低本技能5秒冷却时间。\n获得三张<HighLight>命运黄牌</>；若<HighLight>灵性蓝牌</>数量更多，则改为获得三张<HighLight>灵性蓝牌</>。\n\n<FaintYellow>命运黄牌</>/<FaintYellow>灵性蓝牌</>：获得三张<HighLight>命运黄牌</>/<HighLight>灵性蓝牌</>时消耗所有卡牌，使<HighLight>终结技能洗牌</>切换至<HighLight>命运愚弄</>/<HighLight>灵性爆发</>。\n<FaintYellow>卡牌能量</>：最多持有5点，达到5点时<HighLight>终结技能</>切换并锁定为<HighLight>洗牌</>。"] = "Восполняет собственную <HighLight>Энергию карт</> до 5 очков. При применении каждое очко <HighLight>Энергии карт</> сокращает время перезарядки этого навыка на 5 сек.\nДарует три <HighLight>Жёлтые карты судьбы</>; если количество <HighLight>Синих карт духовности</> больше, вместо этого дарует три <HighLight>Синие карты духовности</>.\n\n<FaintYellow>Жёлтая карта судьбы</>/<FaintYellow>Синяя карта духовности</>: при получении трёх <HighLight>Жёлтых карт судьбы</>/<HighLight>Синих карт духовности</> расходуются все карты, а <HighLight>завершающий навык «Перетасовка»</> сменяется на <HighLight>«Одурачивание судьбы»</>/<HighLight>«Духовный взрыв»</>.\n<FaintYellow>Энергия карт</>: можно накопить до 5 очков. При достижении 5 очков <HighLight>завершающий навык</> сменяется и блокируется на навыке <HighLight>«Перетасовка»</>.",
    ["层叠之门"] = "Многослойные врата",
    ["展开岁月的棋局，自身获得<HighLight>3</>秒<HyperLink stylename=\"M_Link\" u=\"11\">霸体</>，并在*f秒后对周身范围内敌方造成*d点魔法伤害并以*f**的基础概率使最多四名敌人<HyperLink stylename=\"M_Link\" u=\"2\">浮空</>，同时降低自身所有<HighLight>职业技能</>的冷却时间<HighLight>3</>秒，期间自身可以移动。施法后获得20点<HighLight>神秘知识</>。\n\n<FaintYellow>神秘知识</>：最多拥有100点。达到100点时解锁<HighLight>终结技能信息洪流</>。"] = "Разворачивает шахматную партию времён, давая себе <HighLight>3</> сек. <HyperLink stylename=\"M_Link\" u=\"11\">суперброни</>. Через *f сек. наносит врагам вокруг *d ед. магического урона и с базовым шансом *f** <HyperLink stylename=\"M_Link\" u=\"2\">подбрасывает</> до четырёх врагов. Одновременно уменьшает Откат Навыка всех ваших <HighLight>классовых навыков</> на <HighLight>3</> сек. В это время можно двигаться. После применения даёт 20 ед. <HighLight>тайного знания</>.\n\n<FaintYellow>Тайное знание</>: максимум 100 ед. При достижении 100 ед. открывается <HighLight>завершающий навык «Поток информации»</>.",
    ["展开心灵灯塔持续4秒，周身8米范围内的至多6名友方成员免疫<HyperLink stylename=\"M_Link\" u=\"21\">净化</>(优先小队成员)。"] = "Разворачивает Маяк разума на 4 сек.: до 6 союзников в радиусе 8 м вокруг получают невосприимчивость к <HyperLink stylename=\"M_Link\" u=\"21\">Очищению</> (в приоритете члены отряда).",
    ["展开皇帝的新衣，获得<HighLight>2.5</>秒<HyperLink stylename=\"M_Link\" u=\"11\">霸体</>和buffdisc(*id)（此护盾受自身最大生命值加成），持续<HighLight>15</>秒。护盾消失或被击破后，对周身敌方造成相当于护盾伤害吸收量<HighLight>5</>倍基础值的魔法伤害，最高不超过spellfielddisc(*id)点，伤害由范围内的敌方分摊。施法后获得20点<HighLight>神秘知识</>。\n\n<FaintYellow>神秘知识</>：最多拥有100点。达到100点时解锁<HighLight>终结技能信息洪流</>。"] = "Разыграйте «Новый наряд императора»: вы получаете <HighLight>2,5</> секунды <HyperLink stylename=\"M_Link\" u=\"11\">Суперброни</> и buffdisc(*id) (этот щит усиливается вашим максимальным здоровьем) на <HighLight>15</> секунд. После того как щит исчезнет или будет разрушен, окружающим врагам наносится магический урон, равный <HighLight>5</> базовым значениям поглощённого щитом урона, но не более spellfielddisc(*id) очков; урон распределяется между врагами в радиусе действия. После применения вы получаете 20 очков <HighLight>Таинственного знания</>.\n\n<FaintYellow>Таинственное знание</>: максимум 100 очков. При достижении 100 очков открывается <HighLight>завершающий навык «Поток информации»</>.",
    ["展开跟随自己移动的黄昏领域，使范围内的敌方持续滞涩。"] = "Разворачивает Сумеречную область, следующую за вами, и постоянно накладывает замедление на врагов в её пределах.",
    ["展开跟随自己移动的黄昏领域，使范围内至多6名敌方玩家持续<HyperLink stylename=\"M_Link\" u=\"9\">滞涩</>，领域持续<HighLight>6秒</>。"] = "Разворачивает Сумеречную область, следующую за вами: до 6 вражеских игроков в её пределах постоянно находятся под действием <HyperLink stylename=\"M_Link\" u=\"9\">застоя</>. Область действует <HighLight>6 сек.</>.",
    ["展开领域，为领域内生命最低的两名队友提供高额护盾和<HighLight>15%</>的减伤（如果领域内只有自己，则护盾量翻倍），对周身范围内敌方造成*d点物理伤害；随后持续蓄力并<HyperLink stylename=\"M_Link\" u=\"11\">霸体</>，结束时对周身范围内敌方造成*d点物理伤害，此伤害和护盾受自身最大生命值加成。\n施法时消耗所有<HighLight>黄昏印记</>，使本技能获得<HighLight>强化</>。\n\n<FaintYellow>强化</>\n每消耗1点黄昏印记，提供的护盾提高<HighLight>25%</>。"] = "Расширьте поле, чтобы обеспечить высокий щит и снижение урона на <HighLight>15%</> двум товарищам по команде с самым низким уровнем здоровья в поле (если вы единственный в поле, количество щита удваивается), нанося *d очков физического урона врагам в окружающей области; затем продолжайте атаковать и <HyperLink stylename=\"M_Link\" u=\"11\">Суперброня</> и в конце нанесите *d единиц физического урона врагам в окружающей области. Этот урон и щит дополняются собственным максимальным значением здоровья. \nПоглотите всю <HighLight>Сумеречную метку</> при произнесении, делая этот навык <HighLight> усиленным</>. \n\n<FaintYellow> Усиление </>\n Каждый раз, когда расходуется 1 очко Знака Сумрака, предоставляемый щит увеличивается на <HighLight>25%</>.",
    ["展开领域，自身buffdisc(*id)，大范围内队友buffdisc(*id)，自身和队友获得<HighLight>10%</>的减伤，对周身范围内敌方造成*d点物理伤害；随后持续蓄力并<HyperLink stylename=\"M_Link\" u=\"11\">霸体</>，结束时对周身范围内敌方造成*d点物理伤害，此伤害和护盾受自身最大生命值加成。\n施法时消耗所有<HighLight>黄昏印记</>，使本技能获得<HighLight>强化</>。\n\n<FaintYellow>强化</>\n每消耗1点黄昏印记，提供的护盾提高<HighLight>25%</>。"] = "Разворачивает область: накладывает buffdisc(*id) на себя и buffdisc(*id) на союзников в обширной зоне, дарует себе и союзникам <HighLight>10%</> снижения урона и наносит *d ед. физического урона врагам вокруг. Затем накапливает заряд, получая <HyperLink stylename=\"M_Link\" u=\"11\">Суперброню</>, и по завершении наносит *d ед. физического урона врагам вокруг. Этот урон и прочность щита зависят от максимального запаса здоровья.\nПри активации поглощает все <HighLight>Метки сумерек</>, даруя навыку <HighLight>усиление</>.\n\n<FaintYellow>Усиление</>\nКаждая поглощенная Метка сумерек увеличивает прочность щита на <HighLight>25%</>.",
    ["岁月的棋局"] = "Гамбит эпох",
    ["巨人体魄"] = "Телосложение исполина",
    ["巨剑斩"] = "Рубящий удар двуручным мечом",
    ["巨剑斩击"] = "Удар двуручным мечом",
    ["巨剑斩击本体效果"] = "Эффект основы удара двуручным мечом",
    ["巨剑斩击肉鸽本体效果"] = "Эффект основы удара двуручным мечом (рогалик)",
    ["巫术"] = "Колдовство",
    ["并持续对敌人发射多发空气弹，造成5次bulletdisc(*id)点魔法伤害并<HyperLink stylename=\"M_Link\" u=\"2\">打断</>敌方怪物。"] = "И продолжайте стрелять по врагу несколькими воздушными бомбами, нанося 5 раз по bulletdisc(*id) ед. магического урона и <HyperLink stylename=\"M_Link\" u=\"2\"> прерывая </> вражеских монстров.",
    ["幻术戏法"] = "Иллюзорный трюк",
    ["廷根老司机"] = "Бывалый извозчик Тингена",
    ["开启后，10秒内伤害加深提高30%。记录期间你对敌人造成的总伤害，在效果结束时对范围内目标造成一次性伤害，伤害量等于记录总伤害的50%。"] = "После активации на 10 сек. усиление урона повышается на 30%. Записывается весь урон, нанесённый вами врагам за этот период; по окончании эффекта цели в радиусе получают однократный урон, равный 50% записанного общего урона.",
    ["开启窥秘之眼看破假象，以自己为中心造成范围伤害并击退敌人，移除敌方的护盾，造成减疗效果；二段可快速后撤位移。释放后获得神秘知识（用于解锁终结技能）。"] = "Открывает Глаза Тайноведения, прозревая сквозь иллюзии: наносит урон по области вокруг себя и отбрасывает врагов, снимая с них щиты и ослабляя получаемое ими исцеление. Вторая стадия позволяет совершить быстрый отскок назад. После применения дарует оккультные знания (используются для разблокировки завершающих навыков).",
    ["开牌"] = "Вскрытие карты",
    ["开门"] = "Открытие двери",
    ["异端裁决"] = "Суд над ересью",
    ["引导冷静与沉着的精神能量在队友间传递，为传递到的队友回复生命。"] = "Направляет волну спокойствия и душевного равновесия между союзниками, восстанавливая ОЗ каждому затронутому соратнику.",
    ["引爆衰败"] = "Взрыв Увядания",
    ["引黄昏巨人血脉为力，以武器大师天赋为技，凝聚非凡力量，唤出对应的大剑、双剑武器实体形态。"] = "Черпая мощь из родословной Сумеречного Гиганта и мастерство из таланта Мастера Оружия, сгущает потустороннюю силу и материализует физические формы двуручного меча и парных клинков.",
    ["引黄昏巨人血脉为力，以武器大师天赋为技，凝聚非凡力量，唤出对应的大剑、双剑武器实体形态。\n使自己的直觉加4，武力加2。"] = "Черпая мощь из родословной Сумеречного Гиганта и мастерство из таланта Мастера Оружия, сгущает потустороннюю силу и материализует физические формы двуручного меча и парных клинков.\nПовышает собственную Интуицию на 4 и Силу на 2.",
    ["彩虹"] = "Радуга",
    ["彩虹！"] = "Радуга!",
    ["心灵之火"] = "Пламя разума",
    ["心灵引导"] = "Духовное руководство",
    ["心灵慰藉"] = "Утешение разума",
    ["心灵灯塔"] = "Маяк разума",
    ["心理学隐身"] = "Психологическая невидимость",
    ["心理暗示"] = "Психологическое внушение",
    ["心理治疗"] = "Психотерапия",
    ["怒意猛击"] = "Яростный удар",
    ["恶魔果实"] = "Дьявольский плод",
    ["情绪光谱"] = "Спектр эмоций",
    ["惩戒"] = "Кара",
    ["愈心"] = "Исцеление сердца",
    ["意识冲击"] = "Удар по сознанию",
    ["意识操纵"] = "Манипуляция сознанием",
    ["愚者祝福"] = "Благословение Шута",
    ["感受刺骨的寒风。"] = "Ощутите леденящий порыв ветра.",
    ["感知灵界与空间，打开一扇传送门，学徒可以通过这个传送门进行穿梭。"] = "Ощущая духовный мир и пространство, открывает портал, через который может перемещаться Ученик.",
    ["感知灵界与空间，打开一扇传送门，学徒可以通过这个传送门进行穿梭。\n仅可在廷根使用。\n使自身获得直觉加1。"] = "Ощущая духовный мир и пространство, открывает портал, через который может перемещаться Ученик.\nМожно использовать только в Тингене.\nПовышает собственную Интуицию на 1.",
    ["感知灵界，观测星空，通过灵性物品启示的命运变化，解读其映射的现实空间异动、事态发展走向与潜在未知危险。"] = "Воспринимайте мир духов, наблюдайте за звездным небом и интерпретируйте аномалии в реальном пространстве, развитие событий и потенциальные неизвестные опасности, нанесенные на карту изменениями судьбы, раскрываемыми духовными предметами.",
    ["感知灵界，观测星空，通过灵性物品启示的命运变化，解读其映射的现实空间异动、事态发展走向与潜在未知危险。\n占星启示期间，周围的玩家可以获得临时技能来获取占星指引。\n使自身获得武力加4，直觉加2。使用临时技能获取占星指引的玩家也可以获得武力加4，直觉加2。"] = "Ощущая мир духов и взирая на звездное небо, истолковывает изменения судьбы через откровения духовных предметов, распознавая отраженные в них аномалии реального пространства, ход событий и неведомые опасности.\nВо время действия «Астрологического откровения» окружающие игроки получают временный навык для обретения астрологических указаний.\nДает персонажу силу +4, интуицию +2. Игроки, использовавшие временный навык для получения астрологических указаний, также получают силу +4, интуицию +2.",
    ["戏法演绎"] = "Исполнение фокуса",
    ["战士作为天生的武器大师，能够熟练使用多种武器。输出形态下使用双剑，提高自身伤害；防御形态下使用巨剑，获得减伤并更易吸引怪物仇恨。"] = "Воин, будучи прирождённым мастером оружия, виртуозно владеет многими видами вооружения. В атакующей стойке он сражается парными мечами, увеличивая наносимый урон, а в защитной стойке держит двуручный меч, снижая получаемый урон и эффективнее привлекая внимание монстров.",
    ["战斗时神秘外溢，干扰敌人，释放普攻或者技能时有几率额外释放一个知识漩涡，造成伤害和减疗。"] = "В бою мистическая сила выплёскивается наружу, сбивая с толку врагов. Базовые атаки и применение навыков с некоторой вероятностью создают дополнительный Вихрь знаний, наносящий урон и снижающий эффективность исцеления.",
    ["战魂残影"] = "Остаточный образ боевого духа",
    ["手握巨剑如飓风般不断旋转挥砍，持续造成范围伤害，自身持续获得黄昏印记（用于强化怒意猛击和终结技能），并将怪物拖拽，对玩家减速。防御形态可嘲讽怪物。"] = "Вращается с двуручным мечом подобно урагану, непрерывно нанося урон по области. Персонаж непрерывно накапливает Знаки Сумерек (используются для усиления «Яростного удара» и завершающих навыков), притягивает монстров и замедляет игроков. В оборонительной форме способен провоцировать монстров.",
    ["手握巨剑如飓风般不断旋转挥砍，持续造成范围伤害，自身持续获得黄昏印记（用于强化怒意猛击和终结技能），并拖拽怪物，对敌方玩家减速。防御形态可嘲讽怪物。"] = "Вращайте двуручный меч подобно урагану, непрерывно нанося урон по площади. Вы непрерывно накапливаете Метки Сумерек (усиливают «Яростный сокрушительный удар» и завершающие навыки), притягиваете монстров и замедляете вражеских игроков. В защитной стойке провоцирует монстров.",
    ["手握巨剑旋转挥砍，首次攻击对周身敌方造成*d点物理伤害，随后持续打击周身敌方，每<Highlight>0.4</>秒对周身范围内敌方造成*d点物理伤害，共持续<Highlight>5</>秒，并将敌方怪物<HyperLink stylename=\"M_Link\" u=\"2\">拖拽</>向自身，使敌方玩家buffdisc(*id)，旋转结束时对周身敌方造成*d点物理伤害。施法时每秒获得1枚<HighLight>黄昏印记</>，最多获得4枚。\n日暮飓风技能持续期间获得<HyperLink stylename=\"M_Link\" u=\"11\">霸体</>，技能施法期间可以移动，施法1秒后可以再次点按来提前打断施法，对周身敌方造成*d点物理伤害，并返还部分技能冷却时间。\n若自身处于<HighLight>防御形态</>，打击将对敌方怪物附加*f秒<HyperLink stylename=\"M_Link\" u=\"12\">嘲讽</>。\n\n<FaintYellow>黄昏印记</>\n使<HighLight>终结技能</>和<HighLight>怒意猛击</>得到强化，最多持有6枚。"] = "Вращаясь с огромным мечом в руках, вы наносите удары: первая атака наносит окружающим врагам *d физ. урона, затем вы продолжаете бить окружающих врагов, нанося им *d физ. урона каждые <Highlight>0.4</> сек. в течение <Highlight>5</> сек., <HyperLink stylename=\"M_Link\" u=\"2\">притягиваете</> вражеских монстров к себе и накладываете на вражеских игроков buffdisc(*id). По окончании вращения окружающие враги получают *d физ. урона. Во время применения каждую секунду вы получаете 1 <HighLight>Знак сумерек</>, максимум 4.\nВо время действия навыка «Вихрь заката» вы получаете <HyperLink stylename=\"M_Link\" u=\"11\">суперброню</>. Во время применения можно двигаться; спустя 1 сек. после начала можно нажать ещё раз, чтобы досрочно прервать применение: окружающие враги получат *d физ. урона, и часть Отката Навыка вернётся.\nЕсли вы в <HighLight>защитной стойке</>, удары накладывают на вражеских монстров <HyperLink stylename=\"M_Link\" u=\"12\">провокацию</> на *f сек.\n\n<FaintYellow>Знак сумерек</>\nУсиливает <HighLight>завершающий навык</> и <HighLight>яростный удар</>. Можно держать не более 6.",
    ["手握巨剑旋转挥砍，首次攻击对周身敌方造成*d点物理伤害，随后持续打击周身敌方，每<Highlight>0.4</>秒对周身范围内敌方造成*d点物理伤害，共持续<Highlight>5</>秒，并将敌方怪物<HyperLink stylename=\"M_Link\" u=\"2\">拖拽</>向自身，使敌方玩家buffdisc(*id)，旋转结束时对周身敌方造成*d点物理伤害。施法时每秒获得1枚<HighLight>黄昏印记</>，最多获得4枚。\n日暮飓风技能持续期间获得<HyperLink stylename=\"M_Link\" u=\"11\">霸体</>，技能施法期间可以移动，施法1秒后可以释放连招以打断施法，对周身敌方造成*d点物理伤害，并返还部分技能冷却时间。\n若自身处于<HighLight>防御形态</>，打击将对敌方怪物附加*f秒<HyperLink stylename=\"M_Link\" u=\"12\">嘲讽</>。\n\n<FaintYellow>黄昏印记</>\n使<HighLight>终结技能</>和<HighLight>怒意猛击</>得到强化，最多持有6枚。"] = "Вращаясь с огромным мечом в руках, вы наносите удары: первая атака наносит окружающим врагам *d физ. урона, затем вы продолжаете бить окружающих врагов, нанося им *d физ. урона каждые <Highlight>0.4</> сек. в течение <Highlight>5</> сек., <HyperLink stylename=\"M_Link\" u=\"2\">притягиваете</> вражеских монстров к себе и накладываете на вражеских игроков buffdisc(*id). По окончании вращения окружающие враги получают *d физ. урона. Во время применения каждую секунду вы получаете 1 <HighLight>Знак сумерек</>, максимум 4.\nВо время действия навыка «Вихрь заката» вы получаете <HyperLink stylename=\"M_Link\" u=\"11\">суперброню</>. Во время применения можно двигаться; спустя 1 сек. после начала можно выполнить комбо, чтобы прервать применение: окружающие враги получат *d физ. урона, и часть Отката Навыка вернётся.\nЕсли вы в <HighLight>защитной стойке</>, удары накладывают на вражеских монстров <HyperLink stylename=\"M_Link\" u=\"12\">провокацию</> на *f сек.\n\n<FaintYellow>Знак сумерек</>\nУсиливает <HighLight>завершающий навык</> и <HighLight>яростный удар</>. Можно держать не более 6.",
    ["手枪射击"] = "Выстрел из пистолета",
    ["手枪射击+换弹"] = "Выстрел из пистолета + перезарядка",
    ["手枪换弹"] = "Перезарядка пистолета",
    ["手枪瞄准"] = "Прицеливание из пистолета",
    ["执火者"] = "Держатель огня",
    ["技能动态描述模版"] = "Шаблон динамического описания навыка",
    ["抚慰友方目标的心灵，为目标回复一定生命值。"] = "Успокаивает разум союзной цели, восстанавливая ей определенное количество здоровья.",
    ["拍胸脯"] = "Похлопать по груди",
    ["拥有100点<HighLight>神秘知识</>时可以使用。使自身buffdisc(*id)，持续*d秒，在锁定目标的位置召唤信息洪流，信息洪流会以一定速度追击敌方目标，每秒最多对范围内的4名敌方目标造成*d点魔法伤害，每次攻击消耗20点<HighLight>神秘知识</>，<HighLight>神秘知识</>不足时会自动停止。\n信息洪流开启5秒后，每次攻击消耗的<HighLight>神秘知识</>递增10点，消耗<HighLight>30</>/<HighLight>40</>/<HighLight>50</>/<HighLight>60</>/<HighLight>70</>点<HighLight>神秘知识</>时，造成的伤害提升至spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id)点；\n信息洪流自动停止前的攻击次数为\n<HighLight>7</>/<HighLight>8</>/<HighLight>9</>次时，将在结束时对范围内敌方造成spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id)点魔法伤害并有<HighLight>91%</>的基础概率<HyperLink stylename=\"M_Link\" u=\"2\">浮空</>范围内最多两名敌方。"] = "Можно использовать при наличии 100 ед. <HighLight>оккультных знаний</>. Накладывает на себя buffdisc(*id) на *d сек. и призывает в точке выбранной цели Поток информации. Поток информации с определённой скоростью преследует вражеские цели, нанося до 4 врагам в радиусе действия до *d ед. магического урона в секунду. Каждая атака расходует 20 ед. <HighLight>оккультных знаний</>; при их нехватке поток автоматически прекращается.\nЧерез 5 сек. после запуска Потока информации расход <HighLight>оккультных знаний</> на каждую атаку увеличивается на 10 ед. При расходе <HighLight>30</>/<HighLight>40</>/<HighLight>50</>/<HighLight>60</>/<HighLight>70</> ед. <HighLight>оккультных знаний</> наносимый урон возрастает до spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id) ед.\nЕсли до автоматической остановки Поток информации совершил\n<HighLight>7</>/<HighLight>8</>/<HighLight>9</> атак, по завершении он наносит врагам в радиусе действия spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id) ед. магического урона и с базовой вероятностью <HighLight>91%</> накладывает эффект <HyperLink stylename=\"M_Link\" u=\"2\">«Подбрасывание»</> максимум на двух противников в зоне действия.",
    ["拥有<HighLight>星空能量</>不小于3点时可以施放。消耗所有<HighLight>星空能量</>，刺击区域内敌方，造成2次*d点魔法伤害，随后召唤数个残影打击敌人，造成4次*d点魔法伤害，最终引爆星空能量造成*d点魔法伤害。消耗超过3点星空能量时，每多消耗1点星空能量，本技能造成的伤害提高*f**。"] = "Можно применить при наличии не менее 3 ед. <HighLight>энергии звездного неба</>. Расходует всю <HighLight>энергию звездного неба</>, нанося колющий удар по врагам в области и причиняя 2 удара по *d ед. магического урона, затем призывает несколько призрачных теней, атакующих врагов и наносящих 4 удара по *d ед. магического урона, и в конце подрывает энергию звездного неба, нанося *d ед. магического урона. При расходе более 3 ед. энергии звездного неба каждое дополнительное очко увеличивает урон навыка на *f**.",
    ["拥有星空能量不小于3点时可以施放，消耗所有星空能量，首先对敌人发动斩击，随后召唤数个残影打击敌人，最终引爆星空能量造成大量伤害，消耗的星空能量越多，伤害越高。"] = "Можно применить при наличии не менее 3 ед. энергии звездного неба. Расходует всю энергию звездного неба: сначала наносит рубящий удар по врагам, затем призывает несколько призрачных теней для нанесения ударов и, наконец, подрывает энергию звездного неба, нанося огромный урон. Чем больше потрачено энергии звездного неба, тем выше урон.",
    ["拳击普攻"] = "Обычная атака кулаком",
    ["持剑向前高速突进斩击，攻击途经单位并获得黄昏印记（用于强化怒意猛击和终结技能）。攻击形态下附加衰败（持续造成伤害），防御形态下提升自身格挡。"] = "Стремительный рывок вперед с мечом с нанесением рубящего удара, атакуя цели на пути и даруя Метку Сумерек (используется для усиления Яростного удара и завершающих навыков). В атакующей стойке накладывает увядание (периодический урон), а в защитной стойке повышает блок.",
    ["持续<HyperLink stylename=\"M_Link\" u=\"11\">霸体</>，蓄力并持续对周身敌方造成物理伤害，共计<Highlight>4</>次，每次*d点，蓄力结束后对周身敌方造成*d点物理伤害。首次攻击引爆并移除目标身上被附加的<HighLight>衰败</>，剩余时长每多1秒伤害增加*d点。\n施法时消耗所有<HighLight>黄昏印记</>，使本技能获得<HighLight>强化</>。\n\n<FaintYellow>强化</>\n每消耗1点<HighLight>黄昏印记</>，本技能的伤害提高<HighLight>10%</>。"] = "Постоянно <HyperLink stylename=\"M_Link\" u=\"11\">Суперброня</> заряжайтесь и продолжайте наносить физический урон окружающим врагам, всего <Highlight>4</> раз, каждый раз *d очков, после зарядки это нанесёт *d очков физического урона окружающим врагам. Первая атака взрывает и удаляет прикрепленный к цели <HighLight>Decay</>. Урон увеличивается на *d очков за каждую оставшуюся 1 секунду. \n поглощает весь <HighLight> Знак Заката </> при использовании, делая этот навык <HighLight> усиленным </>. \n\n<FaintYellow> Усиление </>\n Каждый раз, когда <HighLight>Сумеречная метка </> потребляет 1 очко, урон от этого умения увеличивается на <HighLight>10%</>.",
    ["持续为周身范围内友方提供心理治疗，为其回复生命值。"] = "Непрерывно проводит психотерапию для союзников поблизости, восстанавливая их здоровье.",
    ["持续对敌人发射多发空气弹。"] = "Непрерывно выпускает во врага несколько Воздушных пуль.",
    ["持续对自己和队友的潜意识进行积极的暗示，获得减伤、霸体并持续治疗周身友方。"] = "Непрерывно посылает позитивные внушения в подсознание себе и союзникам, получая снижение урона, суперброню и постоянно исцеляя союзников вокруг.",
    ["持续治疗周身范围内友方，每1.5秒回复友方*d点生命，上限7次。技能生效期间自身可以移动、释放其它技能。"] = "Непрерывно исцеляет союзников в области действия, восстанавливая соратникам *d ед. здоровья каждые 1,5 сек. (до 7 раз). Во время действия навыка можно передвигаться и применять другие способности.",
    ["持续治疗周身范围内友方，每1.5秒回复范围内友方*d点生命，上限7次。技能生效期间自身可以移动、释放其它技能。\n仅<HighLight>空想姿态</>可用，<HighLight>噩梦姿态</>下切换为<HighLight>心灵之火</>。"] = "Постоянно лечит союзников в радиусе действия и восстанавливает *d очков жизни союзников в радиусе действия каждые 1,5 секунды, до 7 раз. Пока умение действует, вы можете перемещаться и активировать другие умения. \nДоступна только <HighLight>Стойка фантазий</>, <HighLight>Стойка кошмара</> заменена на <HighLight>Внутренний огонь</>.",
    ["挥舞双剑发动暴风骤雨般的攻势造成大量伤害，以连续的挥砍控制敌人，自身获得黄昏印记（用于强化怒意猛击和终结技能）。输出形态下附加衰败（持续造成伤害）。"] = "Взмахивает парными мечами в яростном шквале атак, нанося огромный урон и сдерживая врагов непрерывными ударами; заклинатель получает Метку Сумерек (используется для усиления Яростного удара и завершающих навыков). В атакующей стойке накладывает увядание (периодический урон).",
    ["挥舞巨剑以雷霆之势向左右连续挥砍，随后向前方猛力下劈，造成伤害并获得一枚黄昏印记（用于强化怒意猛击和终结技能）。"] = "Взмахивает двуручным мечом, обрушивая молниеносные удары влево и вправо, после чего совершает сокрушительный рубящий удар вперед, нанося урон и даруя Метку Сумерек (используется для усиления Яростного удара и завершающих навыков).",
    ["掌握各式奇异但危害有限的幻术戏法，通过特质的道具盒展示华丽的表演，愚弄观看者并拍摄记录此刻。\n使自己的学识加3，武力加1。"] = "Овладейте причудливыми, но безобидными иллюзорными фокусами, чтобы показывать эффектные представления с помощью особого реквизита, морочить зрителей и запечатлеть этот миг.\nПовышает собственное Знание на 3 и Силу на 1.",
    ["提膝向前跨步，顺势挥舞长戟向前劈斩，对身前的敌人造成伤害，净化消散状态的敌人并获得太阳能量（用于解锁惩戒和无暗之枪）。"] = "Поднимает колено и делает шаг вперёд, рубя алебардой перед собой: наносит урон врагам впереди, очищает противников в состоянии рассеяния и даёт энергию солнца (необходима для открытия «Кары» и «Копья Бестеневого»).",
    ["摄心"] = "Захват разума",
    ["擅长战斗的噩梦姿态，使用战斗技能造成伤害时，将治疗自身，但自身施加的治疗大幅降低。"] = "Боевая Стойка Кошмара: при нанесении урона боевыми навыками заклинатель исцеляет себя, однако исходящее исцеление значительно снижено.",
    ["擅长治愈的空想姿态，受到控制时，自身会回复生命，但自身造成的伤害大幅降低。"] = "Стойка Фантазии, ориентированная на исцеление: при попадании под контроль восстанавливает здоровье, но наносимый урон значительно снижен.",
    ["操作命运和灵性，并以卡牌的形式具象和愚弄敌人，收集命运黄牌和灵性蓝牌以解锁终结技能命运愚弄和灵性爆发，收集卡牌能量以解锁终结技能洗牌。"] = "Манипулирует судьбой и духовностью, воплощая их в виде карт для одурачивания врагов. Собирайте Желтые карты судьбы и Синие карты духовности, чтобы открыть завершающие навыки «Одурачивание судьбы» и «Всплеск духовности», а также накапливайте энергию карт для открытия завершающего навыка «Перетасовка карт».",
    ["操控目标的灵体之线使其buffdisc(*id)，同时在目标周围展开诡秘之境，使范围内敌方<HyperLink stylename=\"M_Link\" u=\"9\">滞涩</>*f秒，期间造成6次spellfielddisc(*id)点物理伤害；随后终结一击造成spellfielddisc(*id)点物理伤害，若目标为怪物则<HyperLink stylename=\"M_Link\" u=\"2\">浮空</>目标，若目标为玩家则<HyperLink stylename=\"M_Link\" u=\"6\">眩晕</>目标*f秒。施法后获得一张<HighLight>命运黄牌</>；若上次获得为<HighLight>灵性蓝牌</>，则改为获得一张<HighLight>灵性蓝牌</>。\n\n<FaintYellow>命运黄牌</>/<FaintYellow>灵性蓝牌</>：获得三张<HighLight>命运黄牌</>/<HighLight>灵性蓝牌</>时消耗所有卡牌，使<HighLight>终结技能洗牌</>切换至<HighLight>命运愚弄</>/<HighLight>灵性爆发</>。"] = "Управляйте духовной нитью цели, чтобы получить buffdisc(*id), и в то же время распространяйте таинственное царство вокруг цели, заставляя врагов в радиусе действия <HyperLink stylename=\"M_Link\" u=\"9\"> застаиваться</>*f секунд, нанося 6 очков spellfielddisc(*id) в течение этого периода. Физический урон; затем завершающий удар наносит spellfielddisc(*id) ед. физического урона. Если цель — монстр, <HyperLink stylename=\"M_Link\" u=\"2\"> перемещает </> по цели. Если целью является игрок, <HyperLink stylename=\"M_Link\" u=\"6\"> оглушает </> цель на *f секунд. После применения заклинания вы получите <HighLight>Желтую карту судьбы</>; если в прошлый раз вы получили <HighLight>Духовную синюю карту</>, вместо этого вы получите <HighLight>Духовную синюю карту</>. \n\n<FaintYellow>Желтая карта судьбы</>/<FaintYellow>Духовная синяя карта</>: получите три <HighLight>Желтая карта судьбы</>/<HighLight> _Духовная синяя карта</> потребляет все карты, чтобы перемешать <HighLight> завершающие навыки</> переключиться на <HighLight>Судьба Дураки</>/<HighLight>Духовный взрыв</>.",
    ["操纵敌人的灵体之线，控制敌人并造成伤害和减速。"] = "Манипулирует нитями духовного тела врага, подчиняя его, нанося урон и замедляя.",
    ["收起枪械"] = "Убрать огнестрельное оружие",
    ["收集卡牌能量解锁技能。将收集到的所有卡牌能量注入大量卡牌中，向敌人持续倾泻充满能量的卡牌，造成高额伤害，施法过程中可以释放其他技能和移动。"] = "Накапливайте энергию карт для открытия навыка. Вливает всю накопленную энергию карт во множество карт, непрерывно обрушивая заряженные энергией карты на врагов и нанося высокий урон. Во время применения можно использовать другие навыки и передвигаться.",
    ["收集命运黄牌解锁技能。愚弄范围内的敌人，造成大量伤害，之后一段时间自身普通攻击将附加造成额外伤害的愚弄标记且攻击速度提升。使用后获得一点卡牌能量。"] = "Соберите Жёлтые карты судьбы, чтобы открыть навык. Одурачивает врагов в области действия, нанося огромный урон; в течение некоторого времени после этого обычные атаки персонажа накладывают метку одурачивания, наносящую дополнительный урон, а скорость атаки повышается. Использование даёт 1 очко энергии карт.",
    ["收集灵性蓝牌解锁技能。释放自身的灵性力量，对范围内敌人造成大量伤害并附加易伤，使用后获得一点卡牌能量。"] = "Собирайте Синие карты духовности для открытия навыка. Высвобождает силу духовности, нанося огромный урон врагам в области действия и накладывая Уязвимость. Применение дает 1 очко энергии карт.",
    ["改变天空，并召唤<HighLight>“名流之殿”</>。"] = "Изменяет небесный свод и призывает <HighLight>«Зал Славы»</>.",
    ["放逐"] = "Изгнание",
    ["故乡小茉莉"] = "Маленький жасмин с родины",
    ["施展巫术对小范围内敌方进行三段式攻击，分别造成spellfielddisc(*id)/spellfielddisc(*id)/bulletdisc(*id)点魔法伤害并将敌方怪物<HyperLink stylename=\"M_Link\" u=\"2\">打断</>，命中时获得<HighLight>6</>/<HighLight>5</>/<HighLight>13</>点<HighLight>神秘知识</>。自身拥有<HighLight>知识灌注</>时，本技能获得<HighLight>强化</>。\n\n<FaintYellow>强化</>：凝聚三柄朗基努斯之枪掷向指定区域，对小范围内敌方造成spellfielddisc(*id)+spellfielddisc(*id)+spellfielddisc(*id)点魔法伤害，并附加持续*f秒的mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">减疗</>，有<HighLight>50%</>基础概率造成持续<HighLight>3</>秒的<HighLight>50%</>减速效果。同时获得20点<HighLight>神秘知识</>。\n<FaintYellow>神秘知识</>：最多拥有100点。达到100点时解锁<HighLight>终结技能信息洪流</>。"] = "Использует колдовство, проводя трёхэтапную атаку по врагам в небольшой области, нанося соответственно spellfielddisc(*id)/spellfielddisc(*id)/bulletdisc(*id) ед. магического урона и <HyperLink stylename=\"M_Link\" u=\"2\">прерывая</> действия вражеских монстров; при попадании дарует <HighLight>6</>/<HighLight>5</>/<HighLight>13</> ед. <HighLight>Мистических знаний</>. При наличии эффекта <HighLight>Вливание знаний</> навык получает <HighLight>Усиление</>.\n\n<FaintYellow>Усиление</>: материализует три Копья Лонгина и обрушивает их в указанную область, нанося spellfielddisc(*id)+spellfielddisc(*id)+spellfielddisc(*id) ед. магического урона врагам в небольшой области и накладывая mul(*d%,*d) <HyperLink stylename=\"M_Link\" u=\"20\">снижение исцеления</> на *f сек., а также с базовой вероятностью <HighLight>50%</> накладывает <HighLight>50%</> замедление на <HighLight>3</> сек. Одновременно дарует 20 ед. <HighLight>Мистических знаний</>.\n<FaintYellow>Мистические знания</>: можно накопить до 100 ед. При достижении 100 ед. открывается <HighLight>завершающий навык «Информационный поток»</>.",
    ["施展巫术，对目标进行攻击并获得神秘知识（用于解锁终结技能）；释放知识逐人后强化为朗基努斯之枪，伤害与神秘知识获取量提高并附加减疗。"] = "Сотворяет колдовство, атакуя цель и получая тайные знания (используются для открытия завершающих навыков). После применения «Погони за знанием» усиливается до Копья Лонгина: урон и получаемые тайные знания увеличиваются, а также накладывается Снижение лечения.",
    ["施展童话魔法，以神秘力量保护自身，获得护盾、霸体和神秘知识（用于解锁终结技能）。"] = "Сотворяет сказочную магию, защищая себя таинственной силой: дарует щит, Суперброню и тайные знания (используются для открытия завершающих навыков).",
    ["施展童话魔法，展开岁月的棋局加速自身的时间流逝，获得霸体，短暂延迟后造成范围伤害和击飞，同时降低自身技能的冷却时间。释放后获得神秘知识（用于解锁终结技能）。"] = "Сотворяет сказочную магию, разыгрывая Шахматную партию эпох: ускоряет течение собственного времени, даруя Суперброню; после небольшой задержки наносит урон по площади и подбрасывает врагов, сокращая время перезарядки собственных навыков. Применение дает тайные знания (используются для открытия завершающих навыков).",
    ["施展龙威震慑范围内的敌人，造成大量伤害，并击飞处于瘟疫状态的怪物。"] = "Обрушивает Драконье Величие, устрашая врагов в области действия, нанося огромный урон и подбрасывая чудовищ в состоянии чумы.",
    ["施放除普攻外的战斗技能后，会获得1层持续*f秒的<HighLight>足迹</>。\n施放除普攻、解控与终结技能外的战斗技能后，会获得1点<HighLight>星空能量</>。\n\n<FaintYellow>星空能量</>\n<HighLight>星空能量</>最多拥有5点。拥有3点<HighLight>星空能量</>时解锁<HighLight>终结技能层叠之门</>。施放<HighLight>层叠之门</>时会消耗<HighLight>星空能量</>，使其效果获得强化。\n<FaintYellow>足迹</>\n<HighLight>足迹</>最多叠加3层。施放普通攻击<HighLight>闪击</>时消耗所有<HighLight>足迹</>，使其效果获得强化。（若未命中则不会消耗<HighLight>足迹</>。）"] = "После применения боевого навыка, кроме обычной атаки, даёт 1 заряд <HighLight>Следов</> на *f сек.\nПосле применения боевого навыка, кроме обычной атаки, снятия контроля и завершающего навыка, даёт 1 ед. <HighLight>звёздной энергии</>.\n\n<FaintYellow>Звёздная энергия</>\nМаксимум <HighLight>звёздной энергии</> — 5 ед. При 3 ед. <HighLight>звёздной энергии</> открывается <HighLight>завершающий навык «Врата наслоения»</>. При применении <HighLight>Врат наслоения</> расходуется <HighLight>звёздная энергия</>, и их эффект усиливается.\n<FaintYellow>Следы</>\n<HighLight>Следы</> суммируются до 3 раз. При применении обычной атаки <HighLight>Молниеносный удар</> расходуются все <HighLight>Следы</>, и её эффект усиливается. (Если удар не попал, <HighLight>Следы</> не расходуются.)",
    ["旅途"] = "Странствие",
    ["旋动双剑向前方施展迅捷如风的连续剑技，为敌人附加衰败（持续造成伤害），同时自身获得一枚黄昏印记（用于强化怒意猛击和终结技能）。"] = "Вращая парные клинки, обрушивает перед собой стремительную череду ударов, накладывая на противников Увядание (периодический урон) и получая одну Метку Сумерек (используется для усиления Яростного сокрушения и завершающего навыка).",
    ["无暗之枪"] = "Копьё Лишённого Тени",
    ["日暮飓风"] = "Сумеречный Ураган",
    ["星之定位"] = "Определение по звездам",
    ["星云咏叹"] = "Ария туманности",
    ["星光囚笼"] = "Звездная клеть",
    ["星沙"] = "Звездный Песок",
    ["星沙突击"] = "Штурм звёздного песка",
    ["星海穿梭"] = "Странствие по Морю Звезд",
    ["星穹裁决"] = "Суд Звездного Небосвода",
    ["星辰坠落"] = "Звездопад",
    ["普攻"] = "Базовая атака",
    ["普攻灼烧叠至3层会触发范围爆炸并清除层数"] = "При накоплении 3 уровней Горения от базовой атаки происходит взрыв по площади, сбрасывающий уровни эффекта.",
    ["暂离霰弹枪模式"] = "Выход из режима дробовика",
    ["暮色连斩"] = "Сумеречная череда ударов",
    ["朗基努斯之枪"] = "Копье Лонгина",
    ["本姿态下，自身造成的伤害大幅降低，但治疗能力增强且进攻属性可以提升自身的治疗量（提升幅度由属性类别和技能倍率决定）。\n本姿态下，自身受到<HyperLink stylename=\"M_Link\" u=\"3\">控制效果</>时，buffdisc(*id)，持续passivedisc(*id)秒，此效果内置15秒冷却时间。"] = "В этой стойке наносимый вами урон значительно снижен, однако эффективность исцеления повышена, а атакующие характеристики увеличивают объём исцеления (величина зависит от типа характеристики и множителя навыка).\nВ этой стойке при попадании под действие <HyperLink stylename=\"M_Link\" u=\"3\">эффектов контроля</> вы получаете buffdisc(*id) на passivedisc(*id) сек. Внутреннее время восстановления: 15 сек.",
    ["本姿态下，自身除魔法攻击外的进攻属性不再提供治疗量加成且治疗量大幅降低。\n本姿态下，自身造成伤害时会回复自身passivedisc(*id)点生命。"] = "В этой стойке атакующие характеристики персонажа, кроме магической атаки, больше не дают бонуса к лечению, а объём лечения значительно снижается.\nВ этой стойке при нанесении урона восстанавливает персонажу passivedisc(*id) ед. здоровья.",
    ["本技能可充能3次，拥有三种剑法，每次施法后剑法自动变换，不同剑法可相互衔接，分别造成*d、sum(*d+*d)、sum(*d+*d)点物理伤害。\n施法时每段消耗至多2枚<HighLight>黄昏印记</>，使本技能获得<HighLight>强化</>。\n\n<FaintYellow>强化</>\n消耗1/2枚<HighLight>黄昏印记</>，本技能每次的伤害基础值提高*d/*d点。"] = "Этот навык может накапливать до 3 зарядов и включает в себя три техники фехтования. После каждого применения техника автоматически меняется, позволяя связывать их в комбинации и наносить соответственно *d, sum(*d+*d) и sum(*d+*d) ед. физического урона.\nПри каждом ударе можно поглотить до 2 <HighLight>Меток Сумерек</>, чтобы получить <HighLight>усиление</> навыка.\n\n<FaintYellow>Усиление</>\nПоглощение 1/2 <HighLight>Меток Сумерек</> повышает базовый урон каждого удара этого навыка на *d/*d ед.",
    ["机器人跳跃1"] = "Прыжок робота 1",
    ["机器人跳跃2"] = "Прыжок робота 2",
    ["机器人跳跃3"] = "Прыжок робота 3",
    ["机器人闪避"] = "Робот Додж",
    ["权威释放"] = "Высвобождение авторитета",
    ["枪托猛击"] = "Удар прикладом",
    ["梦境分析"] = "Анализ сновидений",
    ["梦境复苏"] = "Восстановление мечты",
    ["梦境编织"] = "Плетение снов",
    ["梦境重生"] = "Возрождение во сне",
    ["模板10"] = "Шаблон 10",
    ["模板3"] = "Шаблон 3",
    ["模板4"] = "Шаблон 4",
    ["模板5"] = "Шаблон 5",
    ["模板6"] = "Шаблон 6",
    ["模板7"] = "Шаблон 7",
    ["模板8"] = "Шаблон 8",
    ["模板9"] = "Шаблон 9",
    ["欢呼"] = "Ликование",
    ["正义审判"] = "Праведный Суд",
    ["武器大师"] = "Мастер оружия",
    ["每次释放普通攻击有<HighLight>5%</>几率、释放战斗技能有<HighLight>15%</>几率向自身面向方向发射知识漩涡，对路径上的敌方造成*d点魔法伤害，并对其造成持续*f秒的mul(*d**,*d)<HyperLink stylename=\"M_Link\" u=\"20\">减疗</>。\n释放普攻或技能后如果没有触发知识漩涡，则概率累计。"] = "Каждая базовая атака с вероятностью <HighLight>5%</>, а боевой навык — с вероятностью <HighLight>15%</> выпускает перед собой вихрь знаний, наносящий *d ед. магического урона врагам на пути и снижающий получаемое ими исцеление на mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\">«Уменьшение исцеления»</> на *f сек.\nЕсли базовая атака или навык не вызвали вихрь знаний, вероятность накапливается.",
    ["永久定身40码内的所有普通敌人。"] = "Навсегда обездвиживает всех обычных врагов в радиусе 40 ярдов.",
    ["永久定身40码内的所有普通敌人，每层只能施放一次。"] = "Навсегда обездвиживает всех обычных врагов в радиусе 40 ярдов. Можно применить лишь раз на каждом этаже.",
    ["汇聚星空能量发动至多四段攻击。收集足迹可施展足迹再现，使闪击得到强化，减少自身技能冷却并对敌人施加概率浮空和减速。"] = "Концентрирует энергию звездного неба для нанесения до четырех ударов. Сбор следов позволяет использовать «Воссоздание следов», усиливая Молниеносный удар, сокращая перезарядку собственных навыков и давая шанс подбросить врагов в воздух и замедлить их.",
    ["治疗波"] = "Исцеляющая волна",
    ["治疗波弹射"] = "Отскок исцеляющей волны",
    ["洗牌"] = "Перетасовка карт",
    ["洞察"] = "Проницательность",
    ["洞察之眼"] = "Око Проницательности",
    ["洞悉并利用敌人的心灵漏洞，造成范围伤害，并附加易伤状态。"] = "Распознает бреши в разуме врагов и обращает их против них: наносит урон по площади и накладывает состояние Уязвимости.",
    ["流星坠落"] = "Падение Метеора",
    ["消耗3点太阳能量凝聚巨锤，以千钧之力向前方砸下，对范围内的敌人造成大量伤害。烈阳状态下得到强化，攻击范围和伤害提升。"] = "Расходует 3 ед. солнечной энергии для сотворения исполинского молота и обрушивает его с сокрушительной силой вперед, нанося огромный урон врагам в области действия. В состоянии Вечно Пылающего Солнца навык усиливается: зона атаки и урон возрастают.",
    ["消耗全部太阳能量，凝聚无暗之枪向敌人掷出，造成的伤害根据消耗的太阳能量大幅增加，并对低生命敌方玩家额外增伤，将被击败的敌方玩家净化。击败玩家重置冷却时间。\n烈阳状态下威力提升，将消耗自身当前生命值一定百分比，造成额外伤害。"] = "Расходует всю накопленную энергию Солнца, создавая Копьё Бессветного и метя его во врага. Наносимый урон многократно возрастает в зависимости от объёма поглощённой энергии Солнца, а вражеские игроки с низким запасом здоровья получают дополнительный урон; побеждённые вражеские игроки очищаются. Победа над игроком сбрасывает время восстановления навыка.\nВ состоянии «Палящее солнце» мощь копья возрастает, расходуя определённый процент текущего здоровья персонажа и нанося дополнительный урон.",
